class Solution {
public:
    int closestMeetingNode(vector<int>& edges, int node1, int node2) {
        int n = edges.size();
        vector<int> dist1(n, -1), dist2(n, -1);

        int d = 0;
        int cur = node1;
        while (cur != -1 && dist1[cur] == -1) {
            dist1[cur] = d;
            d++;
            cur = edges[cur];
        }

        d = 0;
        cur = node2;
        while (cur != -1 && dist2[cur] == -1) {
            dist2[cur] = d;
            d++;
            cur = edges[cur];
        }

        int best = INT_MAX;
        int ans = -1;
        for (int i = 0; i < n; i++) {
            if (dist1[i] != -1 && dist2[i] != -1) {
                int mx = max(dist1[i], dist2[i]);
                if (mx < best) {
                    best = mx;
                    ans = i;
                }
            }
        }
        return ans;
    }
};
